{
  "case_id": "xsu_sg_011_doctor_certificate",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret rammer kernen: ved utilstrækkelig dokumentation kan der indhentes supplerende oplysninger, og lægen beskriver funktionelle begrænsninger, ikke blot diagnose. Men det angiver fejlagtigt, at sagerne behandles af Uddannelses- og Forskningsstyrelsen frem for Udbetaling Danmark, som kilderne (SU-bek. § 36-37) og spørgsmålet peger på. Det siger, at lægeattesten kommer fra 'egen læge eller en behandler', hvilket afviger fra kravet om den praktiserende læge. Det mangler, at lægen skal forholde sig til behov for fortsat behandling eller henvisning til specialist. Det tilføjer desuden afslag på det foreliggende grundlag, som kilderne ikke understøtter."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Første kritiske element er delvist dækket, men attesten beskrives som fra 'egen læge eller en behandler'. Andet element er dækket nogenlunde, da svaret nævner funktionsbegrænsninger, men ikke eksplicit i forhold til den søgte funktionsnedsættelse. Tredje element mangler: behov for fortsat behandling eller henvisning til yderligere udredning/behandling hos en specialist. Svaret nævner kun 'behandling, udvikling og forventet varighed', hvilket ikke er det samme."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvad myndigheden kan gøre ved utilstrækkelig dokumentation, og hvad en lægeattest skal beskrive. Indholdet er relevant, selvom dele er unøjagtige."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så kildernes gyldighed kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så det kan ikke vurderes, om passager understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderstøttet indhold: at Uddannelses- og Forskningsstyrelsen er den behandlende myndighed i stedet for Udbetaling Danmark, at ansøgningen kan afslås, hvis betingelserne ikke er godtgjort, og en detaljeret liste over, hvad attesten 'bør' indeholde (opgaver, belastninger, pauser, variationer, restitution). Kilderne nævner ikke dette. Svaret nævner kun, at der kan fastsættes en frist, men kobler det ikke til dokumentationskravene i § 37, stk. 3-5."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bruger 'kan' og 'kan få en frist' og fremstiller ikke attestindhentning som automatisk pligt. Fremmøde omtales ikke, så det tilhørende forbehold kræves ikke. Det væsentlige forbehold om, at indhentning er en mulighed, er bevaret."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Trinene hænger sammen: utilstrækkelig dokumentation, supplerende oplysninger, frist, afgørelse på det foreliggende grundlag, attestens indhold og myndighedens afgørelse. Der er ingen indre modsigelser, selvom præmisserne delvist er forkerte."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret omformulerer kildens 'skal' (lægen skal forholde sig til funktionsevnen og behov for behandling/henvisning) til det svagere 'bør' for attestens indhold. Dermed gengives modaliteten ikke præcist. 'Kan' for indhentning er korrekt. Svaret tilføjer desuden en afslagsmulighed, som ikke er i kilderne."
    }
  },
  "xhaile_coverage": {
    "A61": {
      "label": "partial",
      "reason": "Svaret dækker, at der kan indhentes en lægeattest, når funktionsniveauet ikke kan vurderes, og at den handler om funktionsevne. Det angiver ikke den praktiserende læge, nævner ikke funktionsevnen i forhold til den søgte funktionsnedsættelse eller behovet for fortsat behandling/henvisning til specialist. Fremmøde, journaloplysninger og udgifter er heller ikke omtalt."
    }
  },
  "overall_notes": "Svaret er læsbart og relevant, men har væsentlige juridiske fejl og mangler: forkert myndighed, manglende kildehenvisninger, udeladelse af behov for behandling/henvisning til specialist og flere uunderstøttede tilføjelser. Mangler kildehenvisning gør C04 not_met og C05/C06 not_assessable."
}

